import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { trackedFiles } from './docs-layout.mjs';
import { blocks, isSampled } from './docs-samples.mjs';

// Two checks of the documentation that read only tracked files:
//
// - The English and Chinese sites are one structure: the same pages, and in
//   each page the same headings by level and the same code blocks by
//   language. A generated page (`<!-- Generated by`) may be English only.
// - Every `wow.*` key a YAML or properties block sets is a key of the Spring
//   Boot configuration metadata (a key, a key below a map or collection key,
//   or a group above keys), compared as Spring binds them (relaxed: case,
//   `-` and `_` do not count). Read: the site's pages, the root READMEs and
//   the Skills.

const ROOT = fileURLToPath(new URL('../..', import.meta.url));
const SITE = 'documentation/docs/';
const LOCALES = ['en', 'zh'];

/** The headings by level and the code blocks by language of a page, without its front matter. */
export function structure(text) {
  const body = text.replace(/^---\n[\s\S]*?\n---\n/, '');
  const headings = [];
  const languages = [];
  let fence;
  for (const line of body.split('\n')) {
    if (fence) {
      if (line.startsWith(fence) && line.trim() === fence) fence = undefined;
      continue;
    }
    const open = /^(`{3,})([\w-]*)/.exec(line);
    if (open) {
      fence = open[1];
      languages.push(open[2] || 'text');
      continue;
    }
    const heading = /^(#{1,6}) /.exec(line);
    if (heading) headings.push(heading[1].length);
  }
  return { headings, blocks: languages };
}

/** The problems between the locales, given each site page's path and text. */
export function localeProblems(pages) {
  const byLocale = Object.fromEntries(
    LOCALES.map(locale => [locale, new Map()]),
  );
  for (const [path, text] of pages) {
    const [locale, ...rest] = path.slice(SITE.length).split('/');
    byLocale[locale]?.set(rest.join('/'), text);
  }
  const [en, zh] = LOCALES.map(locale => byLocale[locale]);
  const problems = [];
  for (const [page, text] of en) {
    if (!zh.has(page)) {
      if (!text.includes('<!-- Generated by'))
        problems.push(
          `${SITE}zh/${page}: missing; ${SITE}en/${page} has no Chinese page`,
        );
      continue;
    }
    const a = structure(text);
    const b = structure(zh.get(page));
    if (a.headings.join() !== b.headings.join())
      problems.push(
        `${SITE}zh/${page}: headings by level [${b.headings}] differ from the English page's [${a.headings}]`,
      );
    if (a.blocks.join() !== b.blocks.join())
      problems.push(
        `${SITE}zh/${page}: code blocks [${b.blocks}] differ from the English page's [${a.blocks}]`,
      );
  }
  for (const page of zh.keys()) {
    if (!en.has(page))
      problems.push(
        `${SITE}en/${page}: missing; ${SITE}zh/${page} has no English page`,
      );
  }
  return problems;
}

const relaxed = key => key.toLowerCase().replace(/[-_]/g, '');

/** A predicate over keys, from the properties of the configuration metadata: `[{ name, type }]`. */
export function knownKeys(properties) {
  const keys = properties.map(({ name, type = '' }) => ({
    name: relaxed(name),
    open: /\b(?:Map|List|Set|Collection)\b/.test(type.replace(/[<.]/g, ' ')),
  }));
  return key => {
    const k = relaxed(key);
    return keys.some(
      ({ name, open }) =>
        k === name ||
        name.startsWith(`${k}.`) ||
        (open && k.startsWith(`${name}.`)),
    );
  };
}

/** The `wow.*` keys a YAML block sets: the dotted path of each key that has a value. */
export function yamlKeys(body) {
  const stack = [];
  const keys = [];
  for (const line of body.split('\n')) {
    const text = line.trim();
    if (
      !text ||
      text.startsWith('#') ||
      text === '---' ||
      text.startsWith('- ')
    )
      continue;
    const match = /^(["']?)([\w.[\]-]+)\1\s*:(?:\s+(.*))?$/.exec(text);
    if (!match) continue;
    const indent = line.length - line.trimStart().length;
    while (stack.length && stack.at(-1).indent >= indent) stack.pop();
    stack.push({ indent, key: match[2] });
    const value = match[3]?.trim();
    const path = stack.map(entry => entry.key).join('.');
    if (path.startsWith('wow.') && value && !/^[#|>]/.test(value))
      keys.push(path);
  }
  return keys;
}

/** The `wow.*` keys a properties block sets. */
export const propertiesKeys = body =>
  body
    .split('\n')
    .map(line => /^\s*(wow\.[^\s=:]+)\s*[=:]/.exec(line)?.[1])
    .filter(Boolean);

/** The problems of one page's configuration blocks against `known`. */
export function configProblems(page, text, known) {
  const problems = [];
  for (const block of blocks(text)) {
    const keys = /^ya?ml$/.test(block.info)
      ? yamlKeys(block.body)
      : block.info === 'properties'
        ? propertiesKeys(block.body)
        : [];
    for (const key of keys.filter(key => !known(key)))
      problems.push(
        `${page}:${block.line}: ${key} is no key of the configuration metadata`,
      );
  }
  return problems;
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  const files = trackedFiles();
  const read = path => readFileSync(join(ROOT, path), 'utf8');
  const metadata = files.filter(
    path =>
      path.endsWith('/META-INF/spring-configuration-metadata.json') &&
      path.includes('/src/main/'),
  );
  const known = knownKeys(
    metadata.flatMap(path => JSON.parse(read(path)).properties),
  );
  const site = files.filter(
    path => path.startsWith(SITE) && path.endsWith('.md'),
  );
  const problems = [
    ...localeProblems(site.map(path => [path, read(path)])),
    ...files
      .filter(isSampled)
      .flatMap(path => configProblems(path, read(path), known)),
  ];
  for (const problem of problems) console.error(problem);
  if (problems.length > 0) process.exit(1);
  console.log(
    `The documentation's locales and configuration keys agree (${site.length} pages)`,
  );
}
